void RunMdbApplyTests(const fs::path& directory,std::ostream& report){
    auto check=[&](bool ok,const char* text){report<<(ok?"PASS: ":"FAIL: ")<<"v0.5.9 "<<text<<std::endl;if(!ok)throw std::runtime_error(text);};
    PhotoSummary summary;summary.values[5]=L"新しいワールド 📷";summary.values[6]=W;summary.values[4]=L"Not a user ID";summary.values[7]=L"Model without ID";summary.values[8]=L"【グループID】"+G;summary.values[9]=L"部分的な記録";summary.values[10]=L"未観測";summary.people={{L"User",U},{L"Name only",L""}};summary.candidatePeople={{L"User",U},{L"候補 📷",V}};
    auto record=PhotoNameInput(summary);IdNameTable original{{W,L"Manual World"},{U,L"User"},{G,L"Keep Group"}};auto plan=BuildPhotoNamePlan(record,original);
    check(plan.added==1&&plan.updated==1&&plan.unchanged==1&&plan.changes.size()==2&&plan.after.at(G)==L"Keep Group"&&original.at(W)==L"Manual World","world and paired users are merged without changing unrelated or original names");
    check(plan.skipped==1&&plan.reasons.count(L"IDなし・不正ID")&&plan.after.size()==4,"name-only record is skipped without reverse lookup or author/model inference");
    record.terms.push_back({1,U,L"Different User",4});record.terms.push_back({1,L"bad",L"Bad ID"});record.terms.push_back({1,T,L""});record.terms.push_back({1,W,L"Wrong prefix"});record.terms.push_back({1,T,L"a\nb"});plan=BuildPhotoNamePlan(record,original);
    check(plan.after.at(U)==L"User"&&plan.reasons.at(L"同じIDの名称不一致")==1&&plan.reasons.count(L"名前なし")&&plan.reasons.count(L"保存できない表示名"),"conflicting ID names invalid types empty names and status text are excluded");
    PhotoSummary nameOnly;nameOnly.values[5]=L"新しいワールド 📷";nameOnly.people={{L"User",L""}};auto empty=BuildPhotoNamePlan(PhotoNameInput(nameOnly),original);check(empty.changes.empty()&&empty.after==original&&empty.skipped==2,"names matching existing aliases cannot recover missing IDs");
    auto noChange=BuildPhotoNamePlan(PhotoNameInput(summary),BuildPhotoNamePlan(PhotoNameInput(summary),original).after);check(noChange.changes.empty()&&noChange.unchanged==3,"repeating an applied image produces no writes");
    auto folder=directory/L"mdb-apply-unit";fs::create_directories(folder);auto path=folder/L"IdDisplayNames.json";fs::remove(path);IdNameStore store;store.Load(path);store.Save(original);auto before=store.Snapshot();store.Save({{G,L"Concurrent change"}});auto bytes=ReadIdNamesFile(path);bool refused=false;try{store.Save(plan.after,&before);}catch(...){refused=true;}check(refused&&ReadIdNamesFile(path)==bytes,"same-process table changes during confirmation cannot be overwritten");
    record.failed=true;refused=false;try{BuildPhotoNamePlan(record,original);}catch(...){refused=true;}check(refused,"metadata read failures cannot form a save proposal");
}
